// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 warpTo, uint256 unlockTime, uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        warpTo = bound(warpTo, 1, 2 ** 60);
        unlockTime = bound(unlockTime, 0, 2 ** 60);
        amount = bound(amount, 1, 10 ether);
        vm.warp(warpTo);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 unlock, ) = c.Acc(actor);
        assertTrue(unlock >= block.timestamp);
    }
}
